<?php require_once __DIR__.'/lib/bootstrap.php'; $d=kcmc_content(); $events=kcmc_active_items($d['events']??[]); usort($events,fn($a,$b)=>strcmp(($a['date']??''),($b['date']??''))); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Events • KCMC Connect</title><link rel="stylesheet" href="styles.css"><style>.page{width:min(900px,calc(100% - 30px));margin:45px auto}.eventx{background:#fff;border:1px solid #dfe5e8;border-radius:18px;padding:20px;margin:14px 0}</style></head><body><main class="page"><a href="./">← KCMC Connect</a><p class="eyebrow">WHAT’S HAPPENING</p><h1>Upcoming events</h1><?php if(!$events): ?><p>No current events are published.</p><?php endif; ?><?php foreach($events as $e): ?><article class="eventx"><small><?=kcmc_h(date('F j, Y',strtotime((string)$e['date'])))?> • <?=kcmc_h((string)$e['time'])?></small><h2><?=kcmc_h((string)$e['title'])?></h2><p><?=kcmc_h((string)($e['location']??'KCMC'))?></p></article><?php endforeach; ?></main></body></html>
